<?php
defined('ABSPATH') || exit;
final class HimeDoll_Inventory_Dashboard {private static ?self $instance=null;public static function instance():self{return self::$instance??=new self();}private function __construct(){add_action('admin_menu',[$this,'menu']);add_action('admin_post_himedoll_inventory_move',[$this,'move']);}
 public function menu():void{add_submenu_page('himedoll-settings','库存管理','库存管理','manage_woocommerce','himedoll-inventory',[$this,'render']);}
 public function move():void{if(!current_user_can('manage_woocommerce'))wp_die('Forbidden');check_admin_referer('himedoll_inventory_move');$qty=(float)($_POST['quantity']??0);HimeDoll_Inventory::instance()->move(absint($_POST['product_id']??0),absint($_POST['warehouse_id']??0),$qty,sanitize_key($_POST['movement_type']??'adjustment'),['note'=>sanitize_text_field(wp_unslash($_POST['note']??''))]);wp_safe_redirect(admin_url('admin.php?page=himedoll-inventory&updated=1'));exit;}
 public function render():void{if(!current_user_can('manage_woocommerce'))return;global $wpdb;$rows=$wpdb->get_results("SELECT l.product_id,l.warehouse_id,w.name,SUM(l.quantity) stock FROM {$wpdb->prefix}hd_inventory_ledger l LEFT JOIN {$wpdb->prefix}hd_warehouses w ON w.id=l.warehouse_id GROUP BY l.product_id,l.warehouse_id ORDER BY l.product_id DESC LIMIT 100",ARRAY_A);?><div class="wrap"><h1>库存管理</h1><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="himedoll_inventory_move"><?php wp_nonce_field('himedoll_inventory_move');?><table class="form-table"><tr><th>商品 ID</th><td><input name="product_id" type="number" required></td></tr><tr><th>仓库</th><td><select name="warehouse_id"><?php foreach(HimeDoll_Inventory::instance()->warehouses() as $w)echo '<option value="'.esc_attr($w['id']).'">'.esc_html($w['name']).'</option>';?></select></td></tr><tr><th>变动类型</th><td><select name="movement_type"><option value="opening">期初</option><option value="adjustment">调整</option><option value="purchase_in">采购入库</option><option value="sale_out">销售出库</option><option value="return_in">退货入库</option></select></td></tr><tr><th>数量</th><td><input name="quantity" type="number" step="0.01" required><p>出库请输入负数。</p></td></tr><tr><th>备注</th><td><input name="note" class="regular-text"></td></tr></table><?php submit_button('登记库存变动');?></form><h2>库存汇总</h2><table class="widefat striped"><thead><tr><th>商品</th><th>仓库</th><th>库存</th></tr></thead><tbody><?php foreach($rows as $r){echo '<tr><td><a href="'.esc_url(get_edit_post_link((int)$r['product_id'])).'">'.esc_html(get_the_title((int)$r['product_id']).' (#'.$r['product_id'].')').'</a></td><td>'.esc_html($r['name']).'</td><td>'.esc_html($r['stock']).'</td></tr>';}?></tbody></table></div><?php }
}
